import requests
import logging
try:
    from urlparse import urljoin
except ImportError:
    from urllib.parse import urljoin
from requests.utils import add_dict_to_cookiejar

from .exceptions import ConnectionError

logger = logging.getLogger(__name__)

# Disable unnecessary urllib warnings relateed to sending unverified requests
# via HTTPS.
DISABLE_WARNINGS = True

if DISABLE_WARNINGS:
    from requests.packages.urllib3.exceptions import InsecureRequestWarning
    requests.packages.urllib3.disable_warnings(InsecureRequestWarning)


# TODO: Remove this and use urllib
class UrlOperations(object):
    @staticmethod
    def process_url(url, port=None):
        url = url.rstrip('/')
        if not url.startswith('http'):
            logger.debug("No protocol defined by user, https will be used.")
            url = "https://" + url
        if port is not None:
            url = '{0}:{1}'.format(url, port)
        return url


class Session(requests.Session):
    """Class responsible for managing the session life cycle.

    Calls Session.teardown() upon being deleted.

        :param str base_url: host to connect to. If no schema is supplied,
            `https://` is used by default. It should not contain port
            designator (e.g. ":8080") - port is specified via `port` parameter.
        :param str username: Username to use for authentication.
        :param str password: Password to use for authentication.
        :param int port: (Optional) port of the target API server.
        :param int timeout: (Optional) timeout for the authentication process
            (in seconds) - None by default (wait indefinitely).
        :raises ConnectionError: If server responds with anything other than
            HTTP 200 during authentication.
        :raises requests.Timeout: If timeout occured.

    Class fields:
        DEFAULT_HEADER - default HTTP headers used by send_request().
        AUTH_ENDPOINT - authorization endpoint URL. Used upon initiating the
            session.
        LOGOUT_ENDPOINT - logout endpoint URL. Used upon call to teardown()
    """
    DEFAULT_HEADER = {'content-type': 'application/json'}
    AUTH_ENDPOINT = 'api/v1/authenticate'
    LOGOUT_ENDPOINT = 'api/v1/logout'

    def __init__(self, base_url, username, password, port=None, timeout=None):
        """Authenticate a new session with RAP Manager.

        Initiates the session, retrieves and stores the session token (cookie).

        For a full description of parameters taken, see this class' docstring.
        """
        super(Session, self).__init__()

        self.url = UrlOperations.process_url(url=base_url, port=port)
        self.authenticated = False

        self._authenticate(username, password, timeout)

    def _authenticate(self, username, password, timeout):
        credentials = {'username': username, 'password': password}
        auth_url = self._get_full_url(self.AUTH_ENDPOINT)
        auth_response = self.post(auth_url, data=credentials, verify=False,
                                  timeout=timeout)
        self.authenticated = auth_response.ok
        if not self.authenticated:
            exc_msg = 'cannot connect: server responded with {}'
            exc_msg = exc_msg.format(auth_response.text)
            raise ConnectionError(exc_msg)

        token = auth_response.json()['token']
        self._add_cookie('token', token)

    def _add_cookie(self, name, value):
        cookie_dict = {name: value}
        add_dict_to_cookiejar(self.cookies, cookie_dict)

    def __del__(self):
        self.teardown()

    def teardown(self, timeout=10):
        """End the session (log out).

        :param int timeout: (Optional) maximum number of seconds to wait for
            the response from the server - 10 by default.
        """
        logout_url = self._get_full_url(self.LOGOUT_ENDPOINT)
        response = self.post(logout_url, verify=False, timeout=timeout)
        response.raise_for_status()
        self.authenticated = False

    def send_request(self, url, method='GET', verify=False, headers=None,
                     **kwargs):
        """Send a request to the server within the scope of this session.

        :param str url: suffix of the URL to use, i.e. the endpoint URL that
            will be appended to the server URL.
        :param str method: (Optional) HTTP method to use for this request, case
            insensitive. Uses "GET" by default.
        :param bool verify: (Optional) if True, TLS certificates will be
            verified upon sending the request. False by default.
        :param dict headers: (Optional) if given, these will be used as the
            request's headers. See Session.DEFAULT_HEADER for the default
            headers used.
        :param kwargs: (Optional) additional arguments given to
            requests.Session internals.

        For a list of possible raised exceptions see documentation of
        requests.Session class.
        """
        if headers is None:
            headers = self.DEFAULT_HEADER
        else:
            headers.update(self.DEFAULT_HEADER)

        request_method = getattr(self, method.lower())
        response = request_method(self._get_full_url(url), verify=verify,
                                  headers=headers, **kwargs)

        response.raise_for_status()
        return response

    def _get_full_url(self, relative_url):
        return urljoin(self.url, relative_url)
